-- Jalankan sekali di Supabase SQL Editor.
create policy "owner manage own campaigns" on public.campaigns for all using (auth.uid()=owner_id or public.is_admin()) with check (auth.uid()=owner_id or public.is_admin());
create policy "owner read own campaigns" on public.campaigns for select using (auth.uid()=owner_id or active=true or public.is_admin());
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$
begin insert into public.profiles(id,display_name,role) values(new.id,coalesce(new.raw_user_meta_data->>'display_name',split_part(new.email,'@',1)),case when coalesce(new.raw_user_meta_data->>'account_type','creator')='campaign_owner' then 'campaign_owner'::public.user_role else 'creator'::public.user_role end) on conflict(id) do nothing; return new; end; $$;
drop trigger if exists on_auth_user_created on auth.users; create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();